style:
/* 墨白 —— 墨黑竖条标题、通栏细线，日期左栏 */

.tw-mobai.layout-formal.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4.4mm;
  border-bottom: none;
  align-items: flex-start;
  gap: 8mm;
}

.tw-mobai.layout-formal.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-mobai.layout-formal.resume-paper .paper-photo {
  order: 3;
  width: 26mm;
  height: 35mm;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.tw-mobai.layout-formal.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #f2f3f4;
  color: #5c6469;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-mobai.layout-formal.resume-paper .paper-name {
  color: #1b1f22;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.06em;
}

.tw-mobai.layout-formal.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6d757a;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-mobai.layout-formal.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: #3d4448;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-mobai.layout-formal.resume-paper .paper-role__label {
  color: #8a9196;
  font-weight: 400;
}

.tw-mobai.layout-formal.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  color: #3a4145;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-mobai.layout-formal.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-mobai.layout-formal.resume-paper .paper-contact + .paper-contact::before {
  content: "";
  left: -3mm;
  width: 0.2mm;
  height: 3.2mm;
  background: #dcdfe1;
  print-color-adjust: exact;
}

.tw-mobai.layout-formal.resume-paper .paper-contact__label {
  color: #868d92;
}

/* 标题：墨黑竖块 + 标题 + 通栏细线 */
.tw-mobai.layout-formal.resume-paper .paper-section__title {
  position: relative;
  display: flex;
  align-items: center;
  gap: 2.6mm;
  margin-bottom: 3.2mm;
  padding: 0 0 1.4mm 0;
  border-bottom: 0.22mm solid #dcdfe1;
  color: #1b1f22;
  font-size: calc(var(--paper-base-size) * 1.1);
  letter-spacing: 0.1em;
}

.tw-mobai.layout-formal.resume-paper .paper-section__title::before {
  content: "";
  flex: 0 0 auto;
  width: 1.4mm;
  height: 5.4mm;
  background: #23282d;
  print-color-adjust: exact;
}

.tw-mobai.layout-formal.resume-paper .paper-section__body {
  color: #33393d;
}

/* 条目：日期左栏，单位居中，岗位贴右 */
.tw-mobai.layout-formal.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
  row-gap: 0.8mm;
}

.tw-mobai.layout-formal.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-mobai.layout-formal.resume-paper .paper-item > .paper-item-head {
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: 6mm;
}

.tw-mobai.layout-formal.resume-paper .paper-item-head .paper-item-title {
  order: 2;
}

.tw-mobai.layout-formal.resume-paper .paper-item-period {
  order: 1;
  flex: 0 0 auto;
  width: 31mm;
  color: #6f777c;
  font-size: calc(var(--paper-base-size) * 0.86);
  white-space: nowrap;
}

.tw-mobai.layout-formal.resume-paper .paper-item > .paper-item-sub {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #40474b;
}

.tw-mobai.layout-formal.resume-paper .paper-item-title {
  color: #1b1f22;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-mobai.layout-formal.resume-paper .paper-item-sub span + span::before {
  content: "";
  margin-right: 5mm;
}

.tw-mobai.layout-formal.resume-paper .paper-item + .paper-item {
  margin-top: 3.4mm;
  padding-top: 2.6mm;
  border-top: 0.2mm dotted #dcdfe1;
}

/* 技能：两列，名称在左、熟练度在右 */
.tw-mobai.layout-formal.resume-paper .paper-skills {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2.4mm 12mm;
}

.tw-mobai.layout-formal.resume-paper .paper-skill {
  padding-bottom: 1.2mm;
  border-bottom: 0.2mm solid #e3e6e8;
}

.tw-mobai.layout-formal.resume-paper .paper-skill__name {
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-mobai.layout-formal.resume-paper .paper-skill__dots {
  display: none;
}

.tw-mobai.layout-formal.resume-paper .paper-skill__level {
  display: inline;
  color: #5f676c;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-mobai.layout-formal.resume-paper .paper-rich ul,
.tw-mobai.layout-formal.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-mobai.layout-formal.resume-paper .paper-rich li::marker {
  color: #8a9196;
}

.tw-mobai.layout-formal.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #1b1f22;
  font-weight: 600;
}

.tw-mobai.layout-formal.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-mobai.layout-formal.resume-paper .paper-footer {
  border-top: 0.2mm solid #e3e6e8;
  color: #9aa1a5;
}
